package com.yeyamo_mobile.api.notification_service.infrastructure.web;
import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})ResponseEntity<Map<String,Object>>bad(Exception e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"code","INVALID_REQUEST","message",String.valueOf(e.getMessage())));}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<Map<String,Object>>missing(Exception e){return ResponseEntity.status(404).body(Map.of("timestamp",Instant.now(),"status",404,"code","NOTIFICATION_NOT_FOUND","message",e.getMessage()));}}
